import System.Exception;import System.ArgumentException;import System.ArgumentOutOfRangeException;import System.Globalization.NumberFormatInfo;import System.Type;import System.MidpointRounding;import System.Int32;import System.SByte;import System.Byte;import System.UInt16;import System.UInt32;import System.Decimal;import System.Globalization.*;import System.Reflection.*;import System.Runtime.Serialization.*;import System.Text.NormalizationForm;import System.TypeCode;import System.DayOfWeek;import System.DateTimeKind;import java.nio.file.*;import java.util.*;
class MidpointRoundingTypeIdentityProbe {
 interface Action{void run();}
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static String text(String s){if(s.equals("~"))return null;StringBuilder b=new StringBuilder();if(!s.isEmpty())for(String u:s.split(","))b.append((char)Integer.parseInt(u));return b.toString();}
 static int[] sizes(String s){if(s.equals("~"))return null;if(s.isEmpty())return new int[0];String[] p=s.split(",");int[] a=new int[p.length];for(int i=0;i<a.length;i++)a[i]=Integer.parseInt(p[i]);return a;}
 static String csv(int[] a){StringJoiner j=new StringJoiner(",");for(int v:a)j.add(Integer.toString(v));return j.toString();}
 static String outcome(Action a){try{a.run();return "OK";}catch(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),e instanceof ArgumentOutOfRangeException x&&x.get_ActualValue()!=null?x.get_ActualValue().toString():"~");}}
 static void check(String a,String e,String c){if(!a.equals(e))throw new AssertionError(c+" actual="+a+" expected="+e);}
 static String flag(boolean b){return b?"1":"0";}
 static Object enumValue(String name,int v){return switch(name){case "System.MidpointRounding"->MidpointRounding.FromValue(v);case "System.Globalization.DigitShapes"->DigitShapes.FromInt32(v);case "System.Globalization.NumberStyles"->NumberStyles.FromInt32(v);case "System.Globalization.TimeSpanStyles"->TimeSpanStyles.FromInt32(v);case "System.Globalization.DateTimeStyles"->DateTimeStyles.FromInt32(v);case "System.Text.NormalizationForm"->NormalizationForm.FromInt32(v);case "System.Reflection.GenericParameterAttributes"->GenericParameterAttributes.FromInt32(v);case "System.Reflection.BindingFlags"->BindingFlags.FromInt32(v);case "System.Reflection.MemberTypes"->MemberTypes.FromInt32(v);case "System.Reflection.CallingConventions"->CallingConventions.FromInt32(v);case "System.Reflection.MethodImplAttributes"->MethodImplAttributes.FromInt32(v);case "System.Runtime.Serialization.StreamingContextStates"->StreamingContextStates.FromInt32(v);case "System.TypeCode"->Arrays.stream(TypeCode.values()).filter(e->e.get_Value()==v).findFirst().orElseThrow();case "System.DayOfWeek"->DayOfWeek.values()[v];case "System.DateTimeKind"->DateTimeKind.values()[v];case "System.Reflection.ParameterAttributes"->Arrays.stream(ParameterAttributes.values()).filter(e->e.get_Value()==v).findFirst().orElseThrow();default->throw new AssertionError(name);};}
 static Object value(String kind,String value,String enumType){return switch(kind){case "null"->null;case "object"->new Object();case "string"->text(value);case "enum"->enumValue(enumType,Integer.parseInt(value));case "int32"->Integer.valueOf(value);case "int32Facade"->new Int32(Integer.parseInt(value));case "int16"->Short.valueOf(value);case "int64"->Long.valueOf(value);case "sbyte"->new SByte(java.lang.Byte.parseByte(value));case "sbytePrimitive"->java.lang.Byte.valueOf(value);case "byte"->new Byte(Short.parseShort(value));case "uint16"->new UInt16(Integer.parseInt(value));case "uint32"->new UInt32(Long.parseLong(value));case "uint64"->new java.math.BigInteger(value);case "bool"->value.equals("1");case "char"->Character.valueOf((char)Integer.parseInt(value));case "single"->Float.valueOf(value);case "double"->Double.valueOf(value);case "decimal"->Decimal.Parse(value);default->throw new AssertionError(kind);};}
 static String lookup(Type type,String method,Object value){try{return method.equals("IsEnumDefined")?"OK|"+flag(type.IsEnumDefined(value)):"OK|"+units(type.GetEnumName(value));}catch(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),"~");}}
 public static void main(String[] args)throws java.lang.Exception{int calls=0,groups=0;if(Type.GetType("System.MidpointRounding")==null)throw new AssertionError("missing MidpointRounding Type");for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);if(p[0].equals("T")){Type t=Type.GetType("System.MidpointRounding");if(t==null)throw new AssertionError("missing MidpointRounding Type");List<String> actual=List.of(t.get_FullName(),t.get_Name(),t.get_Namespace(),t.get_BaseType().get_FullName(),t.GetEnumUnderlyingType().get_FullName(),flag(t.get_IsEnum()),flag(t.get_IsValueType()),flag(t.get_IsPrimitive()),flag(t.get_IsClass()),flag(t.get_IsInterface()),flag(t.get_IsSealed()),flag(t.get_IsAbstract()),flag(t.get_IsPublic()),flag(t.get_IsVisible()),flag(t.get_HasElementType()),flag(t.get_ContainsGenericParameters()),Integer.toString(t.GetDefaultMembers().length));for(int i=0;i<actual.size();i++)check(actual.get(i),p[i+1],"midpoint trait "+i);groups+=17;continue;}if(p[0].equals("L")){Type found=Type.GetType(p[1],false,p[2].equals("1"));check(units(found==null?null:found.get_FullName()),p[3],"midpoint lookup "+p[1]);groups++;continue;}if(p[0].equals("I")){Type t=Type.GetType(p[1]);check(String.join(",",t.GetEnumNames()),p[2],"names "+p[1]);check(csv(t.GetEnumValuesAsUnderlyingType()),p[3],"underlying values "+p[1]);groups+=2;continue;}Type t=Type.GetType(p[0]);Object v=value(p[2],p[3],p[4]);check(lookup(t,p[1],v),p[5],line);calls++;groups++;}java.lang.System.out.println("PASS MidpointRounding type identity calls="+calls+" groups="+groups);}
}
